local DRY_RUN = true local FOLDER_NAME = "Booths" local W = game:GetService("Workspace") local Sel = game:GetService("Selection") local function isBooth(m) if not m:IsA("Model") then return false end local d = m:FindFirstChild("Display") if not d then return false end if not d:FindFirstChild("BoothOwner") then return false end if not d:FindFirstChild("SurfaceGui") then return false end local a = d:FindFirstChild("Attachment") if not a then return false end if not a:FindFirstChild("ProximityPrompt") then return false end if not m:FindFirstChild("PartNamePlayer") then return false end return true end local folder = W:FindFirstChild(FOLDER_NAME) local found = {} for _, x in ipairs(W:GetDescendants()) do if isBooth(x) then table.insert(found, x) end end print("========================================") print("[Fix] booth models found: " .. #found) print("[Fix] Workspace." .. FOLDER_NAME .. " exists: " .. tostring(folder ~= nil)) if folder then print("[Fix] currently inside folder: " .. #folder:GetChildren()) end print("[Fix] DRY_RUN: " .. tostring(DRY_RUN)) print("========================================") if #found == 0 then warn("[Fix] No booth models found at all.") return end local moved = 0 local renamed = 0 local fixed = 0 if not DRY_RUN then if not folder then folder = Instance.new("Folder") folder.Name = FOLDER_NAME folder.Parent = W end end for i, b in ipairs(found) do local needsMove = (b.Parent ~= folder) local needsName = (b.Name ~= "Booth") if needsMove then moved = moved + 1 end if needsName then renamed = renamed + 1 end if i <= 3 or needsMove then print(string.format("[Fix] %-12s parent=%-12s move=%s rename=%s", b.Name, tostring(b.Parent and b.Parent.Name), tostring(needsMove), tostring(needsName))) end if not DRY_RUN then b.Name = "Booth" b.Parent = folder local d = b.Display d.BoothOwner.Value = nil d.SurfaceGui.ImageLabel.Image = "rbxassetid://821176" d.SurfaceGui.TextLabel.Text = "Unclaimed Booth" local pr = d.Attachment.ProximityPrompt pr.Enabled = true pr.ObjectText = "Claim Booth" local pn = b:FindFirstChild("PartNamePlayer") if pn and pn:FindFirstChild("SurfaceGui") and pn.SurfaceGui:FindFirstChild("TextLabel") then pn.SurfaceGui.TextLabel.Text = "None" end fixed = fixed + 1 end end print("========================================") if DRY_RUN then print(string.format("[Fix] DRY RUN: would move %d, rename %d.", moved, renamed)) print("[Fix] Change DRY_RUN to false at the very start, then run again.") else print(string.format("[Fix] Moved %d, renamed %d, reset %d.", moved, renamed, fixed)) print("[Fix] All booths now in Workspace." .. FOLDER_NAME) pcall(function() Sel:Set(found) end) end print("========================================")
